import sys
import math

INF = int(1e8)

class Node:
    def __init__(self):
        self.left = None
        self.right = None
        self.min = INF
        self.dirty = False
        self.batchSetValue = 0

    @staticmethod
    def setValue(f, t, l, r, val, node):
        if f > r or t < l:
            return
        if f <= l and t >= r:
            node.set_value(val)
            return
        node.push_down()
        m = (l + r) >> 1
        Node.setValue(f, t, l, m, val, node.left)
        Node.setValue(f, t, m + 1, r, val, node.right)
        node.push_up()

    @staticmethod
    def build(l, r):
        node = Node()
        if l != r:
            m = (l + r) >> 1
            node.left = Node.build(l, m)
            node.right = Node.build(m + 1, r)
        else:
            node.left = None
            node.right = None
        node.min = INF
        return node

    @staticmethod
    def query(f, t, l, r, node):
        if f > r or t < l:
            return INF
        if f <= l and r <= t:
            return node.min
        node.push_down()
        m = (l + r) >> 1
        return min(Node.query(f, t, l, m, node.left), Node.query(f, t, m + 1, r, node.right))

    @staticmethod
    def from_array(l, r, data, node):
        if l == r:
            node.min = data[l]
            return
        m = (l + r) >> 1
        Node.from_array(l, m, data, node.left)
        Node.from_array(m + 1, r, data, node.right)
        node.push_up()

    @staticmethod
    def to_array(l, r, data, node):
        if l == r:
            data[l] = node.min
            return
        node.push_down()
        m = (l + r) >> 1
        Node.to_array(l, m, data, node.left)
        Node.to_array(m + 1, r, data, node.right)

    def push_up(self):
        self.min = min(self.left.min, self.right.min)

    def set_value(self, val):
        self.min = val
        self.batchSetValue = val
        self.dirty = True

    def push_down(self):
        if self.dirty:
            self.left.set_value(self.batchSetValue)
            self.right.set_value(self.batchSetValue)
            self.dirty = False

